# _specialist_node()：并行执行所有 Specialist Agent
# 使用 ThreadPoolExecutor 实现并发审查——多个 Agent 同时处理不同任务
# _specialist_node：内部辅助方法，供类内部其他方法调用
def _specialist_node(self, state):
    # 初始化列表 outcomes，用于收集/存储多条数据
    outcomes = []  # 收集每个 Specialist 的执行结果
    # ThreadPoolExecutor：线程池并发执行
    # max_workers 取配置值和任务数的较小值，避免创建多余线程
    with ThreadPoolExecutor(max_workers=min(self.max_workers, len(assignments))) as pool:
        # 为每个 (assignment, agent) 对提交一个并发任务
        futures = {
            pool.submit(self._run_assignment, state, assignment, agent): assignment
            for assignment, agent in zip(assignments, agents)
        }
        # as_completed：按完成顺序收集结果（先完成的先返回，不用等最慢的）
        for future in as_completed(futures):
            outcomes.append(future.result())

    # 容错检查：如果所有 assignment 都失败 → 抛出异常
    if outcomes and all(item["status"] == "failed" for item in outcomes):
        raise RuntimeError("all review assignments failed after retry/replanning")

    # 收集所有 findings 并追踪来源（哪个 Agent 发现了哪个 finding）
    # 初始化字典 finding_sources，用于存储键值对数据
    finding_sources = {}  # finding_key -> [agent_name, ...] 来源列表
    for outcome in outcomes:
        for finding in outcome["findings"]:
            key = finding_key(finding)  # 用 path:line:rule_id 计算唯一键
            sources.setdefault(key, []).append(outcome["agent"])
    return {"specialist_findings": findings, "finding_sources": sources}

# CriticAgent：质疑挑战者——对每个 finding 执行 5 项证据检查
# 角色类比：像法庭上的「辩护律师」，专门挑毛病，质疑证据是否充分
# CriticAgent：核心类，封装了系统的关键行为和状态
class CriticAgent:
    # challenge：公开方法，实现核心业务逻辑
    def challenge(self, finding, parsed, peer_sources=None, round_number=1):
        # 初始化列表 objections，用于收集/存储多条数据
        objections = []  # 收集所有不通过项（objection 触发修订请求）
        # 构建有效位置集合（与 _parse_findings 相同的安全校验）
        valid_locations = {(line.path, line.line) for line in parsed.added_lines}
        # 检查 1：finding 指向的位置必须是真实的新增行
        if (finding.path, finding.line) not in valid_locations:
            objections.append("location is not an added line")
        # 检查 2：finding 引用的证据必须能在源行中找到
        source_line = next((l.content for l in parsed.added_lines
                           if l.path == finding.path and l.line == finding.line), "")
        if not finding.evidence or finding.evidence.strip() not in source_line.strip():
            objections.append("quoted evidence does not match the changed line")
        # 检查 3：解释不能太短（太短说明 LLM 没有认真分析）
        if len(finding.explanation.strip()) < 12:
            objections.append("explanation is not specific enough")
        # 检查 4：修复建议必须可操作（不能太笼统）
        if len(finding.fix.strip()) < 8:
            objections.append("remediation is not actionable")
        # 检查 5：测试建议也必须可操作
        if len(finding.test.strip()) < 8:
            objections.append("test strategy is not actionable")
        # 附加检查：高严重级别但只有 1 个来源 → 需要独立验证（不触发 objection）
        if len(peer_sources or []) < 2 and finding.severity in {CRITICAL, HIGH}:
            questions.append("High-impact claim needs independent verifier evidence.")
        # 置信度调整：有 objection → 大幅降低(-0.35)；多来源一致 → 小幅提升(+0.08)
        adjustment = -.35 if objections else (.08 if len(peer_sources) > 1 else .03)
        return Critique(finding_key, not objections, objections, adjustment, ...)

